  "private": true,
  "scripts": { "dev": "next dev -p 3101", "build": "next build", "start": "next start -p 3101", "test": "node --test --experimental-strip-types --disable-warning=MODULE_TYPELESS_PACKAGE_JSON lib/interview.test.mjs" },
  "dependencies": { "next": "16.4.6", "react": "19.3.1", "react-dom": "19.3.1", "@anthropic-ai/sdk": "^1.8.0" },
  "devDependencies": { "typescript": "^5.9.0", "@types/node": "^24", "@types/react": "^19", "@types/react-dom": "^19" }
