import { NextResponse } from 'next/server';
import { createSession } from '@/lib/session';

export const runtime = 'nodejs';

// Native <form method="post"> target, so starting works without client JS. Redirects to /s/<id> (or back with ?error=).
export async function POST(req: Request) {
  const form = await req.formData().catch(() => null);
  const prompt = String(form?.get('prompt') ?? '').trim();
  const back = (error: string) => NextResponse.redirect(new URL(`/?error=${error}`, req.url), 303);
  if (prompt.length < 4) return back('short');
  if (prompt.length > 1000) return back('long');
  try {
    const id = await createSession(prompt);
    return NextResponse.redirect(new URL(`/s/${id}`, req.url), 303);
  } catch (e) {
    console.error('[step1] create session failed', e);
    return back('server');
  }
}
import { NextResponse } from 'next/server';
import { act, getState, InputError } from '@/lib/session';

export const runtime = 'nodejs';

type Ctx = { params: Promise<{ id: string }> };

export async function GET(_req: Request, { params }: Ctx) {
  const state = getState((await params).id);
  return state ? NextResponse.json(state) : NextResponse.json({ error: '세션을 찾을 수 없어요.' }, { status: 404 });
}

// body: {action: 'answer', turnId, choices: string[], text} | {action: 'wrap' | 'more' | 'back' | 'finish'}
export async function POST(req: Request, { params }: Ctx) {
  const body = await req.json().catch(() => null);
  if (!body || typeof body !== 'object' || Array.isArray(body)) return NextResponse.json({ error: '요청 형식이 잘못됐어요.' }, { status: 400 });
  try {
    const state = await act((await params).id, body as Record<string, unknown>);
    return state ? NextResponse.json(state) : NextResponse.json({ error: '세션을 찾을 수 없어요.' }, { status: 404 });
  } catch (e) {
    if (e instanceof InputError) return NextResponse.json({ error: e.message }, { status: 400 });
    console.error('[step1] action failed', e);
    return NextResponse.json({ error: '처리하지 못했어요. 다시 시도해 주세요.' }, { status: 500 });
  }
}
import { randomUUID } from 'node:crypto';
import { db } from './db';
import { completeJSON, provider } from './llm';
import { ensureSchema } from './schema';
import {
  HARD_CAP, MAX_QUESTIONS, RECOMMEND, TRACKS, CLEAR, QUESTION_SYSTEM, CONCEPT_SYSTEM,
  applyAnswer, blockedTrack, conceptUser, decisions, goalLine, initialLedger, label, mockConcept, mockQuestion,
  overall, parseConcept, parseQuestion, pickTrack, questionUser, resolveAnswer, shouldStop,
  type Answer, type Ledger, type Question, type TrackKey, type Turn,
} from './interview';

type TurnRow = { id: string; idx: number; track: TrackKey; question: string; hint: string | null; options: string; allow_free: number; multi: number; answer: string | null; ledger: string | null; provider: string | null };
type SessionRow = { id: string; prompt: string; status: 'interviewing' | 'done'; ambiguity: number | null; tracks: string | null; created_at: string };

export type TurnView = { id: string; idx: number; track: TrackKey; trackLabel: string; question: string; hint: string; options: string[]; multi: boolean; allowFree: boolean; answer: Answer | null; provider: string };
export type Concept = { what: string; analogy: string; details: string[]; so_what: string; decisions: { track: string; decision: string }[] };
export type State = {
  id: string; prompt: string; status: 'interviewing' | 'done'; createdAt: string;
  overall: number; ledger: { key: TrackKey; label: string; score: number; clear: boolean }[];
  turns: TurnView[]; open: TurnView | null;
  restate: { goal: string; decisions: { track: string; decision: string }[]; fuzzy: string[]; canAskMore: boolean } | null;
  result: { title: string; one_liner: string; concept: Concept; provider: string } | null;
  maxQuestions: number;
};

const now = () => new Date().toISOString();
const newId = () => randomUUID().replaceAll('-', '').slice(0, 10);

function rows(id: string) {
  ensureSchema();
  const s = db().prepare('SELECT * FROM step1_sessions WHERE id = ?').get(id) as SessionRow | undefined;
  if (!s) return null;
  const t = db().prepare('SELECT * FROM step1_turns WHERE session_id = ? ORDER BY idx').all(id) as TurnRow[];
  return { s, t, ledger: JSON.parse(s.tracks ?? '{}') as Ledger };
}

const toTurn = (r: TurnRow): Turn => ({ track: r.track, question: r.question, options: JSON.parse(r.options), answer: r.answer ? JSON.parse(r.answer) : null });

export function getState(id: string): State | null {
  const x = rows(id);
  if (!x) return null;
  const { s, t, ledger } = x;
  const views: TurnView[] = t.map((r) => ({
    id: r.id, idx: r.idx, track: r.track, trackLabel: label(r.track), question: r.question, hint: r.hint ?? '',
    options: JSON.parse(r.options), multi: !!r.multi, allowFree: !!r.allow_free, answer: r.answer ? JSON.parse(r.answer) : null, provider: r.provider ?? '',
  }));
  const open = views.find((v) => !v.answer) ?? null;
  const turns = t.map(toTurn);
  const res = db().prepare('SELECT * FROM step1_results WHERE session_id = ?').get(id) as { title: string; one_liner: string; concept: string; provider: string | null } | undefined;
  const ledgerView = TRACKS.map((tr) => ({ key: tr.key, label: tr.label, score: ledger[tr.key] ?? 1, clear: (ledger[tr.key] ?? 1) <= CLEAR }));
  return {
    id: s.id, prompt: s.prompt, status: s.status, createdAt: s.created_at,
    overall: overall(ledger), ledger: ledgerView, turns: views, open,
    restate: s.status === 'interviewing' && !open
      ? { goal: goalLine(s.prompt, turns), decisions: decisions(turns).map(({ track, decision }) => ({ track, decision })), fuzzy: ledgerView.filter((l) => !l.clear).map((l) => l.label), canAskMore: t.length < HARD_CAP }
      : null,
    result: res ? { title: res.title, one_liner: res.one_liner, concept: JSON.parse(res.concept), provider: res.provider ?? '' } : null,
    maxQuestions: MAX_QUESTIONS,
  };
}

export function listSessions(limit = 20) {
  ensureSchema();
  return db().prepare(`
    SELECT s.id, s.prompt, s.status, s.created_at, r.title, (SELECT COUNT(*) FROM step1_turns t WHERE t.session_id = s.id AND t.answer IS NOT NULL) AS answered
    FROM step1_sessions s LEFT JOIN step1_results r ON r.session_id = s.id ORDER BY s.created_at DESC LIMIT ?`).all(limit) as
    { id: string; prompt: string; status: string; created_at: string; title: string | null; answered: number }[];
}

/** Ask the next question (LLM, or the mock bank when the model is off/fails/breaks a rule). No-op if one is already open. */
async function askNext(id: string, force = false): Promise<void> {
  const x = rows(id)!;
  if (x.t.some((r) => !r.answer) || x.s.status !== 'interviewing') return;
  const turns = x.t.map(toTurn);
  if (turns.length >= HARD_CAP || (!force && shouldStop(x.ledger, turns.length))) return;
  const history = turns.map((t) => t.track);
  const blocked = blockedTrack(history);
  const target = pickTrack(x.ledger, history);
  const mock = () => ({ ...mockQuestion(x.s.prompt, turns, target), ambiguity: x.ledger, done: false });
  const res = await completeJSON(QUESTION_SYSTEM, questionUser(x.s.prompt, turns, x.ledger, target, blocked), mock);
  const parsed = parseQuestion(res.data, blocked);
  const ledger = { ...x.ledger, ...parsed.ledger };
  let q: Question;
  let used: string = res.provider;
  if (parsed.q) q = parsed.q;
  else if (parsed.done && !force && res.provider !== 'mock') {
    db().prepare('UPDATE step1_sessions SET tracks = ?, ambiguity = ? WHERE id = ?').run(JSON.stringify(ledger), overall(ledger), id);
    return; // model says every track is clear: go to the Restate gate
  } else {
    const pick = pickTrack(ledger, history);
    q = mockQuestion(x.s.prompt, turns, pick);
    used = res.provider === 'mock' ? 'mock' : 'mock (LLM 응답을 쓸 수 없어 기본 질문)';
  }
  if (res.error) used = 'mock (LLM 호출 실패)';
  const d = db();
  if (d.prepare('SELECT 1 FROM step1_turns WHERE session_id = ? AND answer IS NULL').get(id)) return; // a parallel request won
  d.prepare('INSERT INTO step1_turns (id, session_id, idx, track, question, hint, options, allow_free, multi, answer, ledger, provider, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, ?, ?, ?)')
    .run(newId(), id, turns.length, q.track, q.question, q.hint, JSON.stringify(q.options), q.allow_free ? 1 : 0, q.multi ? 1 : 0, JSON.stringify(ledger), used, now());
  d.prepare('UPDATE step1_sessions SET tracks = ?, ambiguity = ? WHERE id = ?').run(JSON.stringify(ledger), overall(ledger), id);
}

export async function createSession(prompt: string): Promise<string> {
  ensureSchema();
  const id = newId();
  const ledger = initialLedger(prompt);
  db().prepare('INSERT INTO step1_sessions (id, prompt, status, ambiguity, tracks, created_at) VALUES (?, ?, ?, ?, ?, ?)').run(id, prompt, 'interviewing', overall(ledger), JSON.stringify(ledger), now());
  await askNext(id);
  return id;
}

export class InputError extends Error {}

export async function act(id: string, body: Record<string, unknown>): Promise<State | null> {
  const x = rows(id);
  if (!x) return null;
  const open = x.t.find((r) => !r.answer);
  const d = db();
  switch (body.action) {
    case 'answer': {
      if (x.s.status !== 'interviewing' || !open || body.turnId !== open.id) throw new InputError('이미 답한 질문이에요. 화면을 새로 고쳐 주세요.');
      const options: string[] = JSON.parse(open.options);
      const raw = Array.isArray(body.choices) ? body.choices : [];
      const choices = [...new Set(raw.filter((c): c is string => typeof c === 'string'))];
      if (choices.some((c) => c !== RECOMMEND && !options.includes(c))) throw new InputError('보기에 없는 답이 섞여 있어요.');
      if (!open.multi && choices.length > 1) throw new InputError('이 질문은 하나만 고를 수 있어요.');
      if (choices.includes(RECOMMEND) && choices.length > 1) throw new InputError('‘추천해 줘’는 다른 보기와 함께 고를 수 없어요.');
      const text = typeof body.text === 'string' ? body.text.trim() : '';
      if (text.length > 500) throw new InputError('직접 쓰기는 500자까지예요.');
      if (!open.allow_free && text) throw new InputError('이 질문은 직접 쓰기를 받지 않아요.');
      if (!choices.length && !text) throw new InputError('보기를 고르거나 직접 써 주세요.');
      const answer: Answer = resolveAnswer({ choices, text }, options); // store the recommendation itself, not "추천해 줘"
      const ledger = applyAnswer(x.ledger, open.track, answer);
      d.prepare('UPDATE step1_turns SET answer = ? WHERE id = ?').run(JSON.stringify(answer), open.id);
      d.prepare('UPDATE step1_sessions SET tracks = ?, ambiguity = ? WHERE id = ?').run(JSON.stringify(ledger), overall(ledger), id);
      await askNext(id);
      break;
    }
    case 'wrap': // 여기까지로 정리하기: drop the open question, go to the Restate gate
      if (x.s.status !== 'interviewing') break;
      if (!x.t.some((r) => r.answer)) throw new InputError('질문에 하나 이상 답해야 정리할 수 있어요.');
      if (open) d.prepare('DELETE FROM step1_turns WHERE id = ?').run(open.id);
      break;
    case 'more': // Restate gate: "질문 하나 더"
      if (x.s.status === 'interviewing' && !open) await askNext(id, true);
      break;
    case 'back': { // 이전: drop the open question, reopen the last answered one and restore its ledger
      if (x.s.status !== 'interviewing') break;
      const last = [...x.t].reverse().find((r) => r.answer);
      if (!last) break;
      if (open) d.prepare('DELETE FROM step1_turns WHERE id = ?').run(open.id);
      d.prepare('UPDATE step1_turns SET answer = NULL WHERE id = ?').run(last.id);
      const ledger = last.ledger ?? x.s.tracks ?? '{}';
      d.prepare('UPDATE step1_sessions SET tracks = ?, ambiguity = ? WHERE id = ?').run(ledger, overall(JSON.parse(ledger)), id);
      break;
    }
    case 'finish': { // Restate gate confirmed: write the ELI5 concept
      if (x.s.status !== 'interviewing' || open) throw new InputError('정리할 준비가 아직 안 됐어요.');
      const turns = x.t.map(toTurn);
      if (!turns.length) throw new InputError('질문에 하나 이상 답해야 정리할 수 있어요.');
      const fallback = mockConcept(x.s.prompt, turns);
      const res = await completeJSON(CONCEPT_SYSTEM, conceptUser(x.s.prompt, turns), () => fallback);
      const c = parseConcept(res.data, fallback);
      const concept = { what: c.what, analogy: c.analogy, details: c.details, so_what: c.so_what, decisions: decisions(turns).map(({ track, decision }) => ({ track, decision })) };
      if (rows(id)!.s.status === 'done') break; // a parallel request already finished it
      d.prepare('INSERT OR REPLACE INTO step1_results (session_id, title, one_liner, concept, provider, created_at) VALUES (?, ?, ?, ?, ?, ?)')
        .run(id, c.title, c.one_liner, JSON.stringify(concept), res.error ? 'mock (LLM 호출 실패)' : res.provider, now());
      d.prepare("UPDATE step1_sessions SET status = 'done' WHERE id = ?").run(id);
      break;
    }
    default:
      throw new InputError('알 수 없는 요청이에요.');
  }
  return getState(id);
}

export { provider };

import { randomUUID } from 'node:crypto';
import { db, tableExists } from './db';
import { ensureSchema } from './schema';
import { SEED } from './seed';

export type Status = 'active' | 'frozen' | 'cancelled';
export type Workflow = { id: string; title: string; source: string | null; created_at: string };
export type Card = {
  id: string; workflow_id: string; title: string; description: string; status: Status;
  decision: string | null; x: number; y: number; expanded: boolean; created_at: string;
};
export type Edge = { id: string; workflow_id: string; source: string; target: string };
export type Message = { id: string; card_id: string; role: 'user' | 'agent'; content: string; created_at: string };

const g = globalThis as unknown as { __wfReady?: boolean };

/** The shared DB with workflow-view's tables created and the sample workflow seeded. */
export function wf() {
  const d = db();
  if (!g.__wfReady) {
    ensureSchema(d);
    if (!d.prepare('SELECT 1 FROM wf_workflows LIMIT 1').get()) seed();
    g.__wfReady = true;
  }
  return d;
}

/** BEGIN/COMMIT around fn; node:sqlite has no transaction helper. */
function tx<T>(fn: () => T): T {
  const d = db();
  d.exec('BEGIN IMMEDIATE');
  try {
    const r = fn();
    d.exec('COMMIT');
    return r;
  } catch (e) {
    d.exec('ROLLBACK');
    throw e;
  }
}

const now = () => new Date().toISOString();

// node:sqlite rows have a null prototype and INTEGER flags; normalise once here.
const toCard = (r: Record<string, unknown>): Card => ({
  id: String(r.id), workflow_id: String(r.workflow_id), title: String(r.title), description: String(r.description),
  status: r.status as Status, decision: (r.decision as string | null) ?? null, x: Number(r.x), y: Number(r.y),
  expanded: !!r.expanded, created_at: String(r.created_at),
});
const plain = <T,>(r: unknown) => ({ ...(r as object) }) as T;

export function insertWorkflow(title: string, source: string | null): string {
  const id = randomUUID();
  db().prepare('INSERT INTO wf_workflows (id, title, source, created_at) VALUES (?, ?, ?, ?)').run(id, title, source, now());
  return id;
}

export function insertCard(c: Omit<Card, 'id' | 'created_at' | 'expanded'> & { expanded?: boolean }, at = now()): Card {
  const id = randomUUID();
  db().prepare(
    'INSERT INTO wf_cards (id, workflow_id, title, description, status, decision, x, y, expanded, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
  ).run(id, c.workflow_id, c.title, c.description, c.status, c.decision, c.x, c.y, c.expanded ? 1 : 0, at);
  return { ...c, id, expanded: !!c.expanded, created_at: at };
}

export function insertEdge(workflowId: string, source: string, target: string): Edge {
  const id = randomUUID();
  db().prepare('INSERT INTO wf_edges (id, workflow_id, source, target) VALUES (?, ?, ?, ?)').run(id, workflowId, source, target);
  return { id, workflow_id: workflowId, source, target };
}

export function insertMessage(cardId: string, role: Message['role'], content: string, at = now()): Message {
  const id = randomUUID();
  db().prepare('INSERT INTO wf_messages (id, card_id, role, content, created_at) VALUES (?, ?, ?, ?, ?)').run(id, cardId, role, content, at);
  return { id, card_id: cardId, role, content, created_at: at };
}

export function getCard(id: string): Card | null {
  const r = wf().prepare('SELECT * FROM wf_cards WHERE id = ?').get(id);
  return r ? toCard(r) : null;
}

export function cardMessages(cardId: string): Message[] {
  return wf().prepare('SELECT * FROM wf_messages WHERE card_id = ? ORDER BY created_at, rowid').all(cardId).map((r) => plain<Message>(r));
}

export function getWorkflow(id: string): Workflow | null {
  const r = wf().prepare('SELECT * FROM wf_workflows WHERE id = ?').get(id);
  return r ? plain<Workflow>(r) : null;
}

export function listWorkflows(): Workflow[] {
  return wf().prepare('SELECT * FROM wf_workflows ORDER BY created_at DESC').all().map((r) => plain<Workflow>(r));
}

export function loadWorkflow(id: string) {
  const workflow = getWorkflow(id);
  if (!workflow) return null;
  const d = wf();
  const cards = d.prepare('SELECT * FROM wf_cards WHERE workflow_id = ? ORDER BY created_at, rowid').all(id).map(toCard);
  const edges = d.prepare('SELECT * FROM wf_edges WHERE workflow_id = ?').all(id).map((r) => plain<Edge>(r));
  const messages = d
    .prepare('SELECT m.* FROM wf_messages m JOIN wf_cards c ON c.id = m.card_id WHERE c.workflow_id = ? ORDER BY m.created_at, m.rowid')
    .all(id)
    .map((r) => plain<Message>(r));
  return { workflow, cards, edges, messages };
}

function seed() {
  tx(() => {
    const wid = insertWorkflow(SEED.title, 'seed');
    const ids: Record<string, string> = {};
    const t0 = Date.now() - 60 * 60 * 1000;
    SEED.cards.forEach((c, i) => {
      const at = (k: number) => new Date(t0 + i * 6 * 60 * 1000 + k * 60 * 1000).toISOString();
      const card = insertCard({ workflow_id: wid, title: c.title, description: c.description, status: c.status, decision: c.decision ?? null, x: c.x, y: c.y }, at(0));
      ids[c.key] = card.id;
      c.messages.forEach(([role, content], k) => insertMessage(card.id, role, content, at(k)));
    });
    for (const [a, b] of SEED.edges) insertEdge(wid, ids[a], ids[b]);
  });
}

// ---------- step1 import ----------

const TRACKS: Record<string, string> = {
  // step1's own track keys (step1/lib/interview.ts TRACKS)
  fun: '핵심 재미', role: '플레이어 역할', loop: '코어 루프', win: '이기고 지는 조건', platform: '플랫폼과 한 판 길이',
  mood: '분위기와 그림체', audience: '누가 할 게임인지', unique: '다른 게임과 다른 점',
  // older or LLM-invented keys
  genre: '장르', core_loop: '코어 루프', goal: '목표', player: '플레이어',
  setting: '배경', world: '세계관', character: '캐릭터', characters: '캐릭터', art: '아트', art_style: '아트',
  tone: '분위기', controls: '조작', progression: '성장', difficulty: '난이도', session: '플레이 시간',
  monetization: '수익 모델', scope: '범위', story: '이야기', twist: '차별점', differentiation: '차별점',
};

const short = (s: string, n: number) => (s.length > n ? `${s.slice(0, n - 1)}…` : s);

function answerText(raw: unknown): string {
  if (typeof raw !== 'string' || !raw) return '';
  try {
    const a = JSON.parse(raw) as { choices?: unknown; text?: unknown };
    const parts = [...(Array.isArray(a.choices) ? a.choices.map(String) : []), typeof a.text === 'string' ? a.text.trim() : ''];
    return parts.filter(Boolean).join(', ');
  } catch {
    return raw;
  }
}

/** Create (once per session) a workflow from step1's tables. */
export function importStep1(sessionId: string): { id: string } | { error: string } {
  const source = `step1:${sessionId}`;
  const d = wf();
  const existing = d.prepare('SELECT id FROM wf_workflows WHERE source = ?').get(source);
  if (existing) return { id: String(existing.id) };
  if (!tableExists('step1_sessions') || !tableExists('step1_turns')) {
    return { error: '질문하기 기록이 아직 없어요. 질문하기에서 먼저 답변을 끝내 주세요.' };
  }
  const session = d.prepare('SELECT * FROM step1_sessions WHERE id = ?').get(sessionId);
  if (!session) return { error: '그 질문하기 기록을 찾지 못했어요. 예시 워크플로우를 보여 드려요.' };
  const turns = d.prepare('SELECT * FROM step1_turns WHERE session_id = ? AND answer IS NOT NULL ORDER BY idx').all(sessionId);
  // Import only finished sessions: the workflow is created once per source, so a partial import would stick forever.
  if (session.status !== 'done' || turns.length === 0) {
    return { error: '이 질문하기는 아직 끝나지 않았어요. 질문하기에서 답변을 끝낸 뒤 다시 가져와 주세요. 지금은 예시 워크플로우를 보여 드려요.' };
  }
  const result = tableExists('step1_results') ? d.prepare('SELECT * FROM step1_results WHERE session_id = ?').get(sessionId) : undefined;

  let concept: { what?: string; analogy?: string; details?: string[]; so_what?: string } = {};
  try {
    concept = result ? JSON.parse(String(result.concept)) : {};
  } catch {
    /* keep empty; the one-liner still carries the concept */
  }
  const prompt = String(session.prompt);
  const gameTitle = result ? String(result.title) : short(prompt, 30);
  const oneLiner = result ? String(result.one_liner) : prompt;

  return tx(() => {
    const wid = insertWorkflow(gameTitle, source);
    const PER_ROW = 4;
    const pos = (i: number) => ({ x: (i % PER_ROW) * 360, y: Math.floor(i / PER_ROW) * 280 });
    const t0 = Date.now();
    const at = (i: number, k: number) => new Date(t0 + i * 1000 + k).toISOString();

    const conceptCard = insertCard({
      workflow_id: wid, title: `컨셉: ${short(gameTitle, 24)}`, description: short(oneLiner, 200),
      status: result ? 'frozen' : 'active', decision: result ? (concept.what ? `${oneLiner}\n\n${concept.what}` : oneLiner) : null, ...pos(0),
    }, at(0, 0));
    insertMessage(conceptCard.id, 'user', prompt, at(0, 1));
    if (result) {
      const body = [
        concept.what, concept.analogy && `비유로 말하면: ${concept.analogy}`,
        Array.isArray(concept.details) && concept.details.length ? concept.details.map((x) => `- ${x}`).join('\n') : '',
        concept.so_what && `그래서 좋은 점: ${concept.so_what}`,
      ].filter(Boolean).join('\n\n');
      insertMessage(conceptCard.id, 'agent', `**${gameTitle}**\n\n${oneLiner}${body ? `\n\n${body}` : ''}`, at(0, 2));
    }

    let prev = conceptCard.id;
    turns.forEach((t, n) => {
      const i = n + 1;
      const question = String(t.question);
      const answer = answerText(t.answer) || '(답변 없음)';
      const track = typeof t.track === 'string' ? t.track : '';
      const card = insertCard({
        workflow_id: wid, title: Object.hasOwn(TRACKS, track) ? TRACKS[track] : `${i}번째 질문`, description: question,
        status: 'frozen', decision: answer, ...pos(i),
      }, at(i, 0));
      insertMessage(card.id, 'agent', t.hint ? `${question}\n\n${String(t.hint)}` : question, at(i, 1));
      insertMessage(card.id, 'user', answer, at(i, 2));
      insertEdge(wid, prev, card.id);
      prev = card.id;
    });
    return { id: wid };
  });
}
