import { wf, getCard, cardMessages } from '@/lib/store';
import { decisionFor } from '@/lib/agent';
import { bad, jsonBody } from '@/lib/http';

export const runtime = 'nodejs';

/**
 * { action: 'freeze' } — 동결: active → frozen, writes the decision.
 * { action: 'undo' }   — 취소 on an active card (→ cancelled), 되돌리기 on a frozen/cancelled card (→ active).
 */
export async function POST(req: Request, ctx: { params: Promise<{ id: string }> }) {
  const { id } = await ctx.params;
  const card = getCard(id);
  if (!card) return bad('카드를 찾지 못했어요.', 404);
  const b = await jsonBody(req);
  const action = b?.action;
  const d = wf();

  if (action === 'freeze') {
    if (card.status !== 'active') return bad('진행중인 카드만 동결할 수 있어요.', 409);
    const r = await decisionFor(card, cardMessages(id));
    // the status check in WHERE keeps a concurrent undo from being overwritten while the model was thinking
    const u = d.prepare("UPDATE wf_cards SET status = 'frozen', decision = ? WHERE id = ? AND status = 'active'").run(r.decision, id);
    if (!u.changes) return bad('카드 상태가 바뀌었어요. 새로고침해 주세요.', 409);
    return Response.json({ card: { ...card, status: 'frozen', decision: r.decision }, provider: r.provider, error: r.error });
  }
  if (action === 'undo') {
    const next = card.status === 'active' ? 'cancelled' : 'active';
    d.prepare('UPDATE wf_cards SET status = ?, decision = NULL WHERE id = ?').run(next, id);
    return Response.json({ card: { ...card, status: next, decision: null } });
  }
  return bad("action은 'freeze' 또는 'undo'여야 해요.");
}
import { getCard, getWorkflow, cardMessages, insertMessage } from '@/lib/store';
import { agentReply } from '@/lib/agent';
import { bad, jsonBody, str } from '@/lib/http';

export const runtime = 'nodejs';

/** Send a user message to the card's agent: { content } → { messages: [user, agent], provider, error? } */
export async function POST(req: Request, ctx: { params: Promise<{ id: string }> }) {
  const { id } = await ctx.params;
  const card = getCard(id);
  if (!card) return bad('카드를 찾지 못했어요.', 404);
  if (card.status !== 'active') return bad('동결되거나 취소된 카드에는 메시지를 보낼 수 없어요.', 409);
  const b = await jsonBody(req);
  const content = str(b?.content, 1, 4000);
  if (!content) return bad('메시지는 1~4000자로 써 주세요.');
  const user = insertMessage(id, 'user', content);
  const r = await agentReply(getWorkflow(card.workflow_id)?.title ?? '', card, cardMessages(id));
  const agent = insertMessage(id, 'agent', r.content);
  return Response.json({ messages: [user, agent], provider: r.provider, error: r.error }, { status: 201 });
}
import { getWorkflow, insertCard } from '@/lib/store';
import { bad, jsonBody, num, str } from '@/lib/http';

export const runtime = 'nodejs';

/** Add an active card: { title, description, x, y } */
export async function POST(req: Request, ctx: { params: Promise<{ id: string }> }) {
  const { id } = await ctx.params;
  if (!getWorkflow(id)) return bad('워크플로우를 찾지 못했어요.', 404);
  const b = await jsonBody(req);
  if (!b) return bad('JSON 본문이 필요해요.');
  const title = str(b.title, 1, 80);
  const description = str(b.description ?? '', 0, 400);
  const x = num(b.x);
  const y = num(b.y);
  if (title === null) return bad('제목은 1~80자로 써 주세요.');
  if (description === null) return bad('설명은 400자까지 쓸 수 있어요.');
  if (x === null || y === null) return bad('위치 값이 올바르지 않아요.');
  const card = insertCard({ workflow_id: id, title, description, status: 'active', decision: null, x, y, expanded: true });
  return Response.json({ card }, { status: 201 });
}
// The card's sub-agent: replies in the chat and condenses the chat into a decision when the card is frozen.
